import{_ as a,c as t,o as p,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"12、【否】 坤下乾上","description":"温公易说 - 12、【否】 坤下乾上","frontmatter":{"title":"12、【否】 坤下乾上","description":"温公易说 - 12、【否】 坤下乾上"},"headers":[],"relativePath":"zh/classics/wengong/013.md","filePath":"zh/classics/wengong/013.md"}'),n={name:"zh/classics/wengong/013.md"};function r(o,e,_,c,i,l){return p(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="_12、【否】-坤下乾上" tabindex="-1">12、【否】 坤下乾上 <a class="header-anchor" href="#_12、【否】-坤下乾上" aria-label="Permalink to “12、【否】 坤下乾上”">​</a></h1><p>否之匪人，不利君子贞，大往小来。</p><p>彖曰：否之匪人，不利君子贞，大往小来，则是天地不交而万物不通也，上下不交而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子。小人道长，君子道消也。否之匪人何也？凡君子小人更为否泰也。故君子泰则小人否，君子否则天下乱，小人否则天下治。今大往小来，则君子之道否也，故曰否之匪人。否之所施，非其人也。否者，壅塞使之不进之谓也。</p><p>象曰：天地不交，否。君子以俭德辟难，不可荣以禄。</p><p>初六：拔茅茹，以其彚，贞吉，亨 象曰：拔茅，贞吉，志在君也。</p><p>六二：包承，小人吉，大人否，亨 象曰：大人否，亨，不乱群也。否而得位以柔，应君包承者也。故小人居之则为吉，大人居之则为否。然大人者，体顺履正，和而不同，否不能久，久而必通，故曰亨也。</p><p>六三：包羞 象曰：包羞，位不当也。君子之不得其时也。失位而居于下，则为小人之所侮；居于上，则为君子之所耻。故六三不当其位，而进退包羞也。</p><p>九四：有命，无咎，畴离祉 象曰：有命，无咎，志行也。四者，阴退而阳进之时也。命者，上之所以施于下也。四以阳居上，变否为泰，命之所施必施于贤者。贤人进，则泰之端见矣，故有命无咎。畴者，群阳之谓也。阳德将亨，故曰畴离祉。</p><p>九五：休否，大人吉，其亡其亡，系于苞桑 象曰：大人之吉，位正当也。</p><p>上九：倾否，先否后喜 象曰：否终则倾，何可长也。</p>',10)])])}const h=a(n,[["render",r]]);export{f as __pageData,h as default};
